test('family structure comparison keeps security guards and forklift operators out of adjacent technical families', () => {
    const protective = compareFamilyStructureToQuery(15044, ['agent', 'securitate'], 'ro');
    const ictSupport = compareFamilyStructureToQuery(14942, ['agent', 'securitate'], 'ro');
    const securityShortlist = shortlistFamilyStructureMatches(['agent', 'securitate'], 'ro', { limit: 2 });
    assert.equal(protective.hardRejected, false);
    assert.ok(protective.alignedDimensions.includes('role_heads'));
    assert.ok(protective.alignedDimensions.includes('knowledge_domains'));
    assert.equal(ictSupport.alignedDimensions.includes('work_objects'), false);
    assert.equal(securityShortlist.candidates[0]?.comparison.familyNodeId, 15044);
    const mobilePlant = compareFamilyStructureToQuery(15218, ['stivuitorist', 'operator'], 'ro');
    const toolmaking = compareFamilyStructureToQuery(15109, ['stivuitorist', 'operator'], 'ro');
    const forkliftShortlist = shortlistFamilyStructureMatches(['stivuitorist', 'operator'], 'ro', { limit: 2 });
    assert.equal(mobilePlant.hardRejected, false);
    assert.ok(mobilePlant.alignedDimensions.includes('role_heads'));
    assert.ok(mobilePlant.alignedDimensions.includes('transport_mode'));
    assert.equal(toolmaking.alignedDimensions.includes('role_heads'), false);
    assert.equal(forkliftShortlist.candidates[0]?.comparison.familyNodeId, 15218);
});
