test('family structure shortlist uses all dimensions to narrow potential families', () => {
    const hotelReceptionist = shortlistFamilyStructureMatches(['hotel', 'receptionist'], 'en', { limit: 2 });
    assert.equal(hotelReceptionist.candidates[0]?.comparison.familyNodeId, 14965);
    assert.ok(hotelReceptionist.rejected.some((comparison) => comparison.familyNodeId === 14787));
    const truckDriver = shortlistFamilyStructureMatches(['truck', 'driver'], 'en', { limit: 2 });
    assert.deepEqual(truckDriver.candidates.map((candidate) => candidate.comparison.familyNodeId), [15215]);
    assert.ok(truckDriver.rejected.some((comparison) => comparison.familyNodeId === 15212));
    const networkSecurity = shortlistFamilyStructureMatches(['network', 'security', 'professionals'], 'en', { limit: 2 });
    assert.equal(networkSecurity.candidates[0]?.comparison.familyNodeId, 14808);
    assert.ok(networkSecurity.candidates[0]?.supportDimensions.includes('work_objects'));
});
test('family structure shortlist does not expand family-side curated tokens into adjacent meanings', () => {
    const networkSecurity = shortlistFamilyStructureMatches(['network', 'security', 'professionals'], 'en', { limit: 5 });
    const shortlistedIds = networkSecurity.candidates.map((candidate) => candidate.comparison.familyNodeId);
    assert.equal(shortlistedIds.includes(14787), false);
});
